<script setup>
import {computed,ref,watch,onMounted,onBeforeUnmount} from 'vue';
import AccountPicker from '../finance/AccountPicker.vue';
import {useAccountLookup} from '../../shared/api/account-lookup.js';
const lookup=useAccountLookup();
const props=defineProps({accounts:{type:Array,default:()=>[]},modelValue:{type:Array,default:()=>[]}}),emit=defineEmits(['update:modelValue']);
const tab=ref('agents'),query=ref(''),main=ref(''),branch=ref(''),only=ref(false),page=ref(1);
const agents=computed(()=>props.accounts.filter(a=>a.type!=='system'&&a.type!=='pos'));
const mains=computed(()=>agents.value.filter(a=>a.type==='main_agent'));
function within(a,id){const seen=new Set();while(a&&!seen.has(a.id)){if(String(a.id)===String(id))return true;seen.add(a.id);a=props.accounts.find(p=>Number(p.id)===Number(a.parent_id??a.parent?.id));}return false;}
const branches=computed(()=>agents.value.filter(a=>a.type!=='main_agent'&&(!main.value||within(a,main.value))));
function key(a){return props.modelValue.find(k=>k===`agent:${a.id}`||k===`tree:${a.id}`||k===`pos:${a.id}`);}
function toggle(a,checked,coverage='tree'){emit('update:modelValue',[...props.modelValue.filter(k=>k!==`agent:${a.id}`&&k!==`tree:${a.id}`&&k!==`pos:${a.id}`),...(checked?[`${a.type==='pos'?'pos':coverage}:${a.id}`]:[])]);}
const loaded=ref(null),total=ref(0),loading=ref(false),error=ref('');let timer,reader,revision=0,alive=true;
const pages=computed(()=>Math.max(1,Math.ceil(total.value/20))),rows=computed(()=>loaded.value ?? props.accounts.filter(a=>a.type!=='system'&&(tab.value==='pos'?a.type==='pos':a.type!=='pos')).slice(0,20));
async function load(){reader?.abort();reader=new AbortController();const expected=++revision;loading.value=true;error.value='';try{const ids=[...new Set(props.modelValue.map(value=>Number(value.split(':')[1])))];if(only.value&&!ids.length){loaded.value=[];total.value=0;return;}const result=await lookup.api.list('accounts',{account_types:tab.value==='pos'?['pos']:['main_agent','sub_agent','sub_branch'],ancestor_id:branch.value||main.value,account_query:query.value,...(only.value?{lookup_ids:ids}:{}),page:page.value,per_page:20},reader.signal);if(alive&&expected===revision){loaded.value=result.data;total.value=result.meta.total;lookup.rememberAccounts(result.data);}}catch(failed){if(alive&&expected===revision&&failed.name!=='AbortError')error.value=await lookup.failure(failed);}finally{if(alive&&expected===revision)loading.value=false;}}
watch([tab,query,main,branch,only],()=>{page.value=1;clearTimeout(timer);timer=setTimeout(load,300);});watch(page,load);watch(()=>props.modelValue,()=>{if(only.value)load();});watch(main,()=>branch.value='');onMounted(load);onBeforeUnmount(()=>{alive=false;revision++;reader?.abort();clearTimeout(timer);});
</script>
<template><div class="print-scope-picker"><div class="scope-picker-head"><strong>اختيار النطاق</strong><span class="scope-count">{{modelValue.length}} محدد</span></div><div class="scope-picker-tools"><div class="scope-kind-tabs"><button type="button" :class="{active:tab==='agents'}" @click="tab='agents'">الوكلاء والفروع</button><button type="button" :class="{active:tab==='pos'}" @click="tab='pos'">نقاط البيع</button></div><input v-model="query" type="search" placeholder="بحث بالاسم أو المعرّف…" aria-label="بحث بنطاق الطباعة"></div><div class="scope-picker-filters"><label>الوكيل الرئيسي<AccountPicker v-model="main" :vm="lookup" :parameters="{account_type:'main_agent'}" label="الوكيل الرئيسي"/></label><label>الفرع<AccountPicker v-model="branch" :vm="lookup" :parameters="{account_types:['sub_agent','sub_branch'],ancestor_id:main}" label="الفرع"/></label><label class="scope-selected-filter"><input v-model="only" type="checkbox">عرض المختارين فقط</label></div><p v-if="error" class="notice warn" role="alert">{{error}}</p><p v-if="loading" role="status">جارٍ تحميل الحسابات…</p><div class="scope-options scope-card-grid"><article v-for="a in rows" :key="a.id" class="scope-choice-card" :class="{'is-selected':key(a)}"><label class="scope-choice-main"><input type="checkbox" :checked="!!key(a)" :aria-label="'اختيار '+a.name" @change="toggle(a,$event.target.checked)"><span class="scope-choice-text"><strong>{{a.name}}</strong><small>{{a.parent_name||a.parent?.name||accounts.find(p=>p.id===a.parent_id)?.name||'وكيل رئيسي'}}</small></span></label><select v-if="key(a)&&a.type!=='pos'" class="scope-coverage" :value="key(a).split(':')[0]" @change="toggle(a,true,$event.target.value)"><option value="tree">مع الفروع ونقاط البيع</option><option value="agent">هذا الحساب فقط</option></select></article><p v-if="!rows.length" class="scope-empty">لا توجد نتائج مطابقة</p></div><div class="scope-pagination"><span>عرض {{total?(page-1)*20+1:0}}–{{Math.min(page*20,total)}} من {{total}}</span><div><button type="button" class="btn small" :disabled="page<=1" @click="page--">السابق</button><span>{{page}} / {{pages}}</span><button type="button" class="btn small" :disabled="page>=pages" @click="page++">التالي</button></div></div></div></template>
